  "definitions": [
    {
      "term": {
        "text": "escape sequence",
        "refs": ["Q0001", "Q0003", "Q0004", "Q0005"]
      },
      "definition_text": {
        "text": "An escape sequence is a combination of characters that starts with a backslash (\\) and represents a special character in a Java string, such as a double quote, backslash, newline, or tab.",
        "refs": ["Q0001", "Q0003", "Q0004", "Q0005"]
      },
      "context": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "Including double quotes in a string",
        "refs": ["Q0001"]
      },
      "example_text": {
        "text": "String s = \"Hello \\\"Marsh\\\"\"; // prints Hello \"Marsh\"",
        "refs": ["Q0001"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "Escaping backslashes in a Windows file path",
        "refs": ["Q0002", "Q0003"]
      },
      "example_text": {
        "text": "String path = \"C:\\\\Windows\\\\\"; // prints C:\\Windows\\",
        "refs": ["Q0002", "Q0003"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "Using newline and tab escape sequences",
        "refs": ["Q0004"]
      },
      "example_text": {
        "text": "String s = \"C:\\\\Drive\\n\\tWindows\"; // prints C:\\Drive then a new line and a tab before Windows",
        "refs": ["Q0004"]
      },
      "example_type": null
    }
  ],
  "explanations": [],
  "facts": [
    {
      "fact_text": {
        "text": "In Java strings, a backslash (\\) is used to escape special characters such as double quote (\\\"), backslash (\\\\), newline (\\n), and tab (\\t).",
        "refs": ["Q0001", "Q0003", "Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Four commonly used escape sequences in Java are \\\" (double quote), \\\\ (backslash), \\n (newline), and \\t (tab).",
        "refs": ["Q0005"]
      },
      "fact_type": null
    }
  ],
